// ⚙️ GENEROVANÉ — needituj ručne. Zdroj pravdy: plany/trails-nahadzovac-state.json (done tripy).
// Regeneruj: node plany/gen-hero-trails.mjs
import type { LatLngTuple } from 'leaflet';

export type HeroTrail = {
  id: string; name: string; region: string;
  diff?: 'Easy' | 'Moderate' | 'Hard' | 'Odyssey'; km: string; stars: number;
  path: LatLngTuple[]; photos: string[]; seasons: string[];
  desc: string;
  /** @deprecated zaniklo 13. 9. 2026 — texty sa prilepili k `desc`. Pole tu ostáva, lebo
   *  ADD-flow zápisy v localStorage ho môžu mať uložené zo staršej verzie a zúžený typ by
   *  ich pri čítaní zhodil. Nový výlet ho nedostane. */
  dogNote?: string;
  descEN?: string; dogNoteEN?: string;   // EN preklad popisu (SK je zdroj)
  acts?: string[]; surface?: string[]; crowd?: string; tags?: string[];
  ascentM?: number;   // prevýšenie z DEM eudem25m (m), kalibrované na SNP=29403
  elev?: number[];    // výškový profil (m), downsamplovaný na ~50 bodov rovnomerne po km trasy
  waves?: number;     // vodná plocha: počet vlniek 1|2|3 podľa OSM plochy (100/1000 ha prahy)
  marks?: ('red'|'blue'|'green'|'yellow')[][];  // turistické značky (KČT) — rad ÚSEKOV štart→cieľ, každý = množina súbežných farieb (auto z OSM)
  customPoi?: Array<{ t: 'viewpoint'|'wildlife'|'ticks'|'shelter'; kind: 'point'|'area'; lat: number; lon: number; r?: number; name?: string }>;  // vlastné body/územia z trip-auditu, NIE z OSM (bez ODbL atribúcie)
  parking?: { lat: number; lon: number; note?: string };  // odkiaľ sa vyráža — z neho sa skladajú odkazy do navigácií (tripNav.ts)
  // iterácia 11 (Map /pack/map bod 1) — generovaný dataset nemá per-trip author,
  // UI fallbackuje na 'Hekthor & Matej' (viď tripShared.tsx authorOf). Nové ADD-flow tripy
  // (lokálny session state, nie tento generátor) nesú meno prihláseného člena.
  author?: string;
  // multi-country (2026-07-24): explicitná krajina (ISO2, napr. 'ch') pre ADD-flow tripy mimo SK;
  // ak chýba, trailCountry() ju odvodí z path[0]. Generovaný SK dataset ju nemá (odvodí sa).
  country?: string;
  // KEDY SA IŠLO (2026-08-25) — len ADD-flow výlety, rovnaká konvencia ako author/country.
  // ⚠️ Tento blok je vnútro JS template literalu — žiadne spätné apostrofy v komentároch.
  // Do 25. 8. dátum zo sprievodcu nikam neprežil: zapísal sa výhradne do trip_votes.when,
  // a to ako MESIAC a len keď človek dal labky — bez labiek sa stratil úplne. Pritom je to
  // pole povinné na odoslanie, takže sa vypĺňalo vždy a zahadzovalo takmer vždy. Kurátorovaný
  // dataset ho nemá zámerne (nie je to „bol som tam vtedy", ale trasa).
  date?: string;      // 'YYYY-MM-DD' | 'YYYY-MM' | chýba = „nepamätám"
  dateEnd?: string;   // koniec viacdňového putovania
  // KOĽKO PSOV IŠLO (2026-08-25) — z posádky v sprievodcovi (draft.crew), len ADD-flow výlety.
  // ⚠️ Do 25. 8. sa posádka pri ukladaní ZAHADZOVALA: crew bolo v drafte, do trasy sa nikdy
  // neprepísalo, takže označenie psa nemalo účinok nikde. Matej: "prešiel jeden dogypťan je
  // zle lebo som označil aj hektora."
  // ⚠️ TOTO POLE STÁLO LEN V GENEROVANOM SÚBORE, NIE TU (opravené 2026-08-25) — prvá
  // regenerácia ho ticho zmazala a typová chyba by vyskočila inde než pri príčine.
  dogs?: number;
  // KOTVY PLÁNU (2026-08-25) — len záznamy 'plan-', kurátorovaný dataset ich nemá.
  // 'path' plánu je PRICHYTENÁ stopa (stovky bodov), takže sa z nej nedajú spätne získať
  // kliky, ktoré ju vyrobili. Bez tohto poľa by človek, ktorý po prejdení povie
  // "šiel som inak", musel celú trasu nakresliť odznova namiesto posunutia kotvy.
  planPath?: LatLngTuple[];
  // OKRUH MIESTA (2026-09-01) — len ADD-flow zápisy, kurátorovaný dataset ho nemá.
  // Návšteva a časť aktivít nemajú trasu, ale PLOCHU: stred leží v 'path[0]', polomer tu.
  // ⚠️ Do 1. 9. sa oboje pri ukladaní ZAHADZOVALO ('line' bolo prázdne pole pre všetko,
  // čo nie je 'route'), takže zapísaná návšteva nemala na mape ani jeden bod — vyzeralo to
  // ako prázdny zoznam, nie ako chyba. Jazdec polomeru pritom bežal a človek ním nastavoval
  // číslo, ktoré nikam neviedlo.
  areaR?: number;
};

